// One Timestamp(MICROSECOND) value of 1001: exactly 1.001 milliseconds.
// Generated from a public-engine Arrow stream with its time-unit metadata set
// to MICROSECOND. Importing it as 1 millisecond would silently lose precision.
export const subMillisecondTimestampArrow = '';

// 18446744073709552 seconds overflow int64 when multiplied by 1000. The
// engine alone reads this as 384 milliseconds, so reject before that conversion.
export const wrappedSecondsTimestampArrow = '';
